#include <zephyr/drivers/eeprom.h>
#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/logging/log.h>
#include <string.h>
#include <stdlib.h>

LOG_MODULE_REGISTER(eeprom_emul, CONFIG_EEPROM_LOG_LEVEL);

struct eeprom_emul_config {
    size_t size;
};

struct eeprom_emul_data {
    struct k_mutex mutex;
    uint8_t *buffer;
};

static int eeprom_emul_read(const struct device *dev, off_t offset,
                            void *data, size_t len)
{
    struct eeprom_emul_data *dev_data = dev->data;
    const struct eeprom_emul_config *dev_cfg = dev->config;
    int ret = 0;

    k_mutex_lock(&dev_data->mutex, K_FOREVER);

    /* Validate offset and length */
    if (offset < 0 || (size_t)offset > dev_cfg->size ||
        (size_t)offset + len > dev_cfg->size) {
        LOG_ERR("Read out of bounds: offset %zd, len %zu, device size %zu",
                offset, len, dev_cfg->size);
        ret = -EINVAL;
        goto unlock;
    }

    memcpy(data, dev_data->buffer + offset, len);

unlock:
    k_mutex_unlock(&dev_data->mutex);
    return ret;
}

static int eeprom_emul_write(const struct device *dev, off_t offset,
                             const void *data, size_t len)
{
    struct eeprom_emul_data *dev_data = dev->data;
    const struct eeprom_emul_config *dev_cfg = dev->config;
    int ret = 0;

    k_mutex_lock(&dev_data->mutex, K_FOREVER);

    /* Validate offset and length */
    if (offset < 0 || (size_t)offset > dev_cfg->size ||
        (size_t)offset + len > dev_cfg->size) {
        LOG_ERR("Write out of bounds: offset %zd, len %zu, device size %zu",
                offset, len, dev_cfg->size);
        ret = -EINVAL;
        goto unlock;
    }

    memcpy(dev_data->buffer + offset, data, len);

unlock:
    k_mutex_unlock(&dev_data->mutex);
    return ret;
}

static size_t eeprom_emul_get_size(const struct device *dev)
{
    const struct eeprom_emul_config *dev_cfg = dev->config;
    return dev_cfg->size;
}

static int eeprom_emul_init(const struct device *dev)
{
    struct eeprom_emul_data *dev_data = dev->data;
    const struct eeprom_emul_config *dev_cfg = dev->config;

    k_mutex_init(&dev_data->mutex);

    dev_data->buffer = (uint8_t *)k_malloc(dev_cfg->size);
    if (!dev_data->buffer) {
        LOG_ERR("Failed to allocate EEPROM emulator buffer of size %zu", dev_cfg->size);
        return -ENOMEM;
    }
    memset(dev_data->buffer, 0xFF, dev_cfg->size); /* Initialize with 0xFF (erased state) */

    LOG_DBG("EEPROM emulator initialized with size %zu", dev_cfg->size);
    return 0;
}

static const struct eeprom_driver_api eeprom_emul_api = {
    .read = eeprom_emul_read,
    .write = eeprom_emul_write,
    .get_size = eeprom_emul_get_size,
};

/* Device Tree instance macro */
#define EEPROM_EMUL_DEFINE(n)                                               \
    static struct eeprom_emul_data eeprom_emul_data_##n;                    \
    static const struct eeprom_emul_config eeprom_emul_config_##n = {       \
        .size = DT_INST_PROP(n, size),                                      \
    };                                                                      \
    DEVICE_DT_INST_DEFINE(n, eeprom_emul_init, NULL,                        \
                          &eeprom_emul_data_##n,                            \
                          &eeprom_emul_config_##n,                          \
                          POST_KERNEL, CONFIG_EEPROM_INIT_PRIORITY,         \
                          &eeprom_emul_api);

DT_INST_FOREACH_STATUS_OKAY(EEPROM_EMUL_DEFINE)
